class Solution:
    def isPossibleToSplit(self, nums: List[int]) -> bool:
        counts = {}
        for num in nums:
            counts[num] = counts.get(num, 0) + 1
        
        n = len(nums)
        distinct_count = len(counts)
        
        if distinct_count > n // 2:
            return True
        
        duplicates = 0
        for count in counts.values():
            if count > 2:
                return False
            if count == 2:
                duplicates += 1
        
        if duplicates > n // 2 - distinct_count:
          return False
        
        return True
